-- hts_codes lines → HTS 2026 Revision 21
--
-- Source:    https://www.usitc.gov/sites/default/files/tata/hts/hts_2026_revision_21_json.json
-- Generated by src/scripts/tariff-calculator/build-hts-lines-sync-sql.ts from a read-only snapshot of
--            35805 hts_codes rows (99 chapters) and the edition's 35805 rows.
--
-- What: the edition added and removed HTS lines that the base-rate refresh only reported. For the
-- 1 chapters that differ, this one transaction
--   0. aborts unless those chapters still hold exactly the snapshot's rows (ids + order) — so a stale
--      file, or a second run after it was applied, fails instead of doing damage;
--   1. stages the chapters' edition rows (position = sort_order, parent = nearest row above with indent-1,
--      by the original ingest's indent-stack rule) and resolves each to its existing row — numbered rows by
--      hts_number, unnumbered header rows by indent + description in order — or a new gen_random_uuid() id;
--   2. deletes the 0 numbered + 0 header rows the edition dropped (0 hts_code_candidate_codes links cascade);
--   3. inserts the 293 numbered + 35 header rows it added (rates/units in the original ingest formats);
--   4. re-sequences sort_order and re-points parent_id (and syncs indent/description: 0 re-indented,
--      0 re-described) for every row of those chapters — only differing rows are written;
--   5. SELECTs integrity checks and aborts if any fails (counts per chapter, unique sort_order, parent one
--      indent up in the same chapter, no line outside the edition, overall numbered diff = 0 / 0).
-- 293 of the new numbered rows (and their group rows) are statistical reporting numbers the HTS JSON does not
-- print: Chapter 91 statistical note 1 (8-digit subheading + component suffix), from
-- src/tariff-data/calculator/statistical-suffixes.json (2026 Revision 21). Rates blank: inherited from the subheading.
-- Other chapters are untouched. Removed lines disappear from the /hts-codes/us/[section]/[chapter] pages and
-- from calculator search.
--
-- Apply (never by hand against production):
--   1. Review this file in the PR and merge.
--   2. GitHub Actions → "insights-ui: apply data SQL" → sql_file=insights-ui/prisma/data-sql/tariff-calculator/20261013-2026-revision-21-hts-lines-sync-ch91-statistical-suffixes.sql, dry_run=true
--      (runs everything, prints the checks, then ROLLBACK). Every check must show ok = t.
--   3. Re-run with dry_run=false to COMMIT.
-- Rollback: the generator also writes a rollback file (kept out of the repo) that restores the deleted rows,
-- their candidate-code links and every row's previous sort_order / parent_id / indent / description.
-- See docs/insights-ui/tariffs/calculator-data-refresh.md.
--
-- Affected chapters:
--   chapter | +numbered | -numbered | +headers | -headers | re-indented | re-described | rows now (edition)
--      91   |       293 |         0 |       35 |        0 |           0 |            0 |   314 → 642

BEGIN;

-- ---------------------------------------------------------------------------
-- 0. Guard: the affected chapters still hold exactly the rows this file was generated from
-- ---------------------------------------------------------------------------
CREATE TEMP TABLE tmp_hts_sync_snapshot (chapter_number INT PRIMARY KEY, row_count INT NOT NULL, ids_md5 TEXT NOT NULL) ON COMMIT DROP;
DO $$ DECLARE drifted TEXT; BEGIN
  SELECT string_agg(s.chapter_number::text, ', ' ORDER BY s.chapter_number) INTO drifted
    FROM tmp_hts_sync_snapshot s
    LEFT JOIN tariff_chapters c ON c.space_id = 'koala_gains' AND c.number = s.chapter_number
    LEFT JOIN LATERAL (SELECT count(*)::int AS n, md5(coalesce(string_agg(h.id, ',' ORDER BY h.sort_order, h.id COLLATE "C"), '')) AS m
                         FROM hts_codes h WHERE h.chapter_id = c.id AND h.space_id = 'koala_gains') cur ON true
   WHERE c.id IS NULL OR cur.n <> s.row_count OR cur.m <> s.ids_md5;
  IF drifted IS NOT NULL THEN RAISE EXCEPTION 'hts_codes changed since this file was generated (or it was already applied) in chapter(s) %. Regenerate it.', drifted; END IF; END $$;

-- ---------------------------------------------------------------------------
-- 1. Edition rows of the 1 affected chapters (position = new sort_order; parent_pos = parent's position)
-- ---------------------------------------------------------------------------
CREATE TEMP TABLE tmp_hts_sync (
  chapter_number INT NOT NULL,
  pos INT NOT NULL,
  is_new BOOLEAN NOT NULL,
  header_id TEXT,            -- existing unnumbered header row this position keeps (matched by indent + description in order)
  hts_number TEXT,           -- existing numbered rows are matched on this
  hts_code_10 TEXT,
  indent INT NOT NULL,
  description TEXT NOT NULL,
  unit_of_quantity TEXT[],   -- rate / unit columns are only carried for new rows
  general_rate_of_duty TEXT,
  special_rate_of_duty TEXT,
  column2_rate_of_duty TEXT,
  quota_quantity TEXT,
  additional_duties TEXT,
  parent_pos INT,
  id TEXT,                   -- resolved below: existing id, or gen_random_uuid() for new rows
  PRIMARY KEY (chapter_number, pos)
) ON COMMIT DROP;
ANALYZE tmp_hts_sync;

UPDATE tmp_hts_sync t SET id = h.id
  FROM hts_codes h
 WHERE NOT t.is_new AND t.hts_number IS NOT NULL AND h.space_id = 'koala_gains' AND h.hts_number = t.hts_number;
UPDATE tmp_hts_sync SET id = header_id WHERE NOT is_new AND hts_number IS NULL;
UPDATE tmp_hts_sync SET id = gen_random_uuid()::text WHERE is_new;
DO $$ DECLARE bad INT; BEGIN
  SELECT count(*) INTO bad
    FROM tmp_hts_sync t
    JOIN tariff_chapters c ON c.space_id = 'koala_gains' AND c.number = t.chapter_number
    LEFT JOIN hts_codes h ON h.id = t.id
   WHERE t.id IS NULL
      OR (NOT t.is_new AND (h.id IS NULL OR h.chapter_id <> c.id OR h.hts_number IS DISTINCT FROM t.hts_number))
      OR (t.is_new AND t.hts_number IS NOT NULL AND EXISTS (SELECT 1 FROM hts_codes x WHERE x.space_id = 'koala_gains' AND x.hts_number = t.hts_number));
  IF bad > 0 THEN RAISE EXCEPTION '% edition row(s) could not be matched to the expected hts_codes row (or a new line already exists)', bad; END IF; END $$;

-- ---------------------------------------------------------------------------
-- 2. Delete the 0 rows the edition no longer has (0 hts_code_candidate_codes links cascade with them)
-- ---------------------------------------------------------------------------
CREATE TEMP TABLE tmp_hts_sync_delete (chapter_number INT NOT NULL, hts_number TEXT, id TEXT) ON COMMIT DROP;
-- Numbered rows by hts_number; header rows (no number) by id.
UPDATE tmp_hts_sync_delete d SET id = h.id
  FROM hts_codes h
 WHERE d.hts_number IS NOT NULL AND h.space_id = 'koala_gains' AND h.hts_number = d.hts_number;
DO $$ DECLARE bad INT; BEGIN
  SELECT count(*) INTO bad
    FROM tmp_hts_sync_delete d
    JOIN tariff_chapters c ON c.space_id = 'koala_gains' AND c.number = d.chapter_number
    LEFT JOIN hts_codes h ON h.id = d.id
   WHERE h.id IS NULL OR h.chapter_id <> c.id OR h.hts_number IS DISTINCT FROM d.hts_number OR EXISTS (SELECT 1 FROM tmp_hts_sync t WHERE t.id = d.id);
  IF bad > 0 THEN RAISE EXCEPTION '% row(s) to delete are missing, in another chapter, or still in the edition', bad; END IF; END $$;
SELECT 'hts_code_candidate_codes links removed by cascade (expected 0)' AS step, count(*) AS rows
  FROM hts_code_candidate_codes l WHERE l.hts_code_id IN (SELECT id FROM tmp_hts_sync_delete);
WITH deleted AS (DELETE FROM hts_codes h USING tmp_hts_sync_delete d WHERE h.id = d.id RETURNING h.id)
SELECT 'hts_codes rows deleted (expected 0)' AS step, count(*) AS rows FROM deleted;

-- ---------------------------------------------------------------------------
-- 3. Insert the 328 rows the edition added (parent_id / sort_order are set in step 4)
-- ---------------------------------------------------------------------------
WITH inserted AS (
                         column2_rate_of_duty, quota_quantity, additional_duties, chapter_id, parent_id, sort_order, space_id, created_at, updated_at)
  SELECT t.id, t.hts_number, t.hts_code_10, t.indent, t.description, t.unit_of_quantity, t.general_rate_of_duty, t.special_rate_of_duty,
         t.column2_rate_of_duty, t.quota_quantity, t.additional_duties,
         (SELECT c.id FROM tariff_chapters c WHERE c.space_id = 'koala_gains' AND c.number = t.chapter_number), NULL, t.pos, 'koala_gains', now(), now()
    FROM tmp_hts_sync t WHERE t.is_new ORDER BY t.chapter_number, t.pos
  RETURNING id
)
SELECT 'hts_codes rows inserted (expected 328)' AS step, count(*) AS rows FROM inserted;

-- ---------------------------------------------------------------------------
-- 4. Re-sequence + re-parent every row of the affected chapters (only differing rows change)
-- ---------------------------------------------------------------------------
WITH updated AS (
  UPDATE hts_codes h
     SET sort_order = t.pos, indent = t.indent, description = t.description, parent_id = p.id, updated_at = now()
    FROM tmp_hts_sync t
    LEFT JOIN tmp_hts_sync p ON p.chapter_number = t.chapter_number AND p.pos = t.parent_pos
   WHERE h.id = t.id
     AND (h.sort_order IS DISTINCT FROM t.pos OR h.indent IS DISTINCT FROM t.indent
       OR h.description IS DISTINCT FROM t.description OR h.parent_id IS DISTINCT FROM p.id)
  RETURNING h.id
)
SELECT 'hts_codes rows re-sequenced / re-parented / re-described' AS step, count(*) AS rows FROM updated;

-- ---------------------------------------------------------------------------
-- 5. Integrity checks (all must be 0 / equal; the DO block aborts the transaction otherwise)
-- ---------------------------------------------------------------------------
CREATE TEMP TABLE tmp_hts_edition_numbers (hts_number TEXT PRIMARY KEY) ON COMMIT DROP;
-- All 30154 numbered lines of the edition, for the overall diff.
ANALYZE tmp_hts_edition_numbers;
CREATE TEMP TABLE tmp_hts_sync_checks (check_name TEXT PRIMARY KEY, actual BIGINT NOT NULL, expected BIGINT NOT NULL) ON COMMIT DROP;
CREATE TEMP TABLE tmp_hts_sync_rows ON COMMIT DROP AS
  SELECT h.id, h.hts_number, h.indent, h.parent_id, h.sort_order, h.chapter_id, c.number AS chapter_number
    FROM hts_codes h JOIN tariff_chapters c ON c.id = h.chapter_id
   WHERE h.space_id = 'koala_gains' AND c.space_id = 'koala_gains' AND c.number IN (91);
SELECT 'affected chapters whose row count differs from the edition', count(*), 0
  FROM (SELECT t.chapter_number, count(*) AS n FROM tmp_hts_sync t GROUP BY 1) e
  LEFT JOIN (SELECT chapter_number, count(*) AS n FROM tmp_hts_sync_rows GROUP BY 1) r ON r.chapter_number = e.chapter_number
 WHERE r.n IS DISTINCT FROM e.n
UNION ALL
SELECT 'duplicate sort_order within an affected chapter', count(*), 0
  FROM (SELECT chapter_id, sort_order FROM tmp_hts_sync_rows GROUP BY 1, 2 HAVING count(*) > 1) d
UNION ALL
SELECT 'rows not at their edition position (sort_order / indent / number)', count(*), 0
  FROM tmp_hts_sync t LEFT JOIN tmp_hts_sync_rows r ON r.id = t.id
 WHERE r.id IS NULL OR r.sort_order <> t.pos OR r.indent <> t.indent OR r.hts_number IS DISTINCT FROM t.hts_number
UNION ALL
SELECT 'rows whose parent is not in the same chapter, one indent up, and above them', count(*), 0
  FROM tmp_hts_sync_rows r LEFT JOIN hts_codes p ON p.id = r.parent_id
 WHERE (r.indent = 0 AND r.parent_id IS NOT NULL)
    OR (r.parent_id IS NOT NULL AND (p.id IS NULL OR p.chapter_id <> r.chapter_id OR p.indent <> r.indent - 1 OR p.sort_order >= r.sort_order))
UNION ALL
SELECT 'rows whose parent_id is not the nearest indent-1 row above them (indent-stack rule)', count(*), 0
  FROM tmp_hts_sync t
  JOIN tmp_hts_sync_rows r ON r.id = t.id
  LEFT JOIN tmp_hts_sync p ON p.chapter_number = t.chapter_number AND p.pos = t.parent_pos
 WHERE r.parent_id IS DISTINCT FROM p.id
UNION ALL
SELECT 'indent>0 rows without a parent (chapter-leading section headers, indent gaps in the edition)', count(*), 0
  FROM tmp_hts_sync_rows r WHERE r.indent > 0 AND r.parent_id IS NULL
UNION ALL
SELECT 'rows in affected chapters whose hts_number is not in the edition', count(*), 0
  FROM tmp_hts_sync_rows r
 WHERE r.hts_number IS NOT NULL AND NOT EXISTS (SELECT 1 FROM tmp_hts_edition_numbers e WHERE e.hts_number = r.hts_number)
UNION ALL
SELECT 'edition numbered lines missing from hts_codes (all chapters)', count(*), 0
  FROM tmp_hts_edition_numbers e
 WHERE NOT EXISTS (SELECT 1 FROM hts_codes h WHERE h.space_id = 'koala_gains' AND h.hts_number = e.hts_number)
UNION ALL
SELECT 'hts_codes numbered lines not in the edition (all chapters)', count(*), 0
  FROM hts_codes h
 WHERE h.space_id = 'koala_gains' AND h.hts_number IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM tmp_hts_edition_numbers e WHERE e.hts_number = h.hts_number);

SELECT r.chapter_number, count(*) AS rows, e.n AS edition_rows, count(*) = e.n AS ok
  FROM tmp_hts_sync_rows r
  JOIN (SELECT chapter_number, count(*) AS n FROM tmp_hts_sync GROUP BY 1) e ON e.chapter_number = r.chapter_number
 GROUP BY r.chapter_number, e.n ORDER BY r.chapter_number;
SELECT check_name, actual, expected, actual = expected AS ok FROM tmp_hts_sync_checks ORDER BY check_name;
DO $$ DECLARE failed TEXT; BEGIN
  SELECT string_agg(check_name || ' = ' || actual || ' (expected ' || expected || ')', '; ' ORDER BY check_name) INTO failed
    FROM tmp_hts_sync_checks WHERE actual <> expected;
  IF failed IS NOT NULL THEN RAISE EXCEPTION 'hts_codes integrity check failed: %', failed; END IF; END $$;

COMMIT;
